// Global variables
let currentModal = null;
let searchIndex = [];

// Initialize application when DOM is ready
document.addEventListener('DOMContentLoaded', function() {
  initializeApp();
});

function getBookSlug(book) {
    const url = book.main_url || book.pdf_url || '';
    const match = url.match(/\/(?:books|pdfviewer)\/([^\/\?]+)/);
    return match ? match[1] : null;
}

function initializeApp() {
  buildSearchIndex();
  renderLibrary();
  setupEventListeners();
}

// Build search index for quick searching
function buildSearchIndex() {
  searchIndex = [];
  
  Object.entries(libraryData.categories).forEach(([categoryName, categoryData]) => {
    // If this is a group, index books from each subcategory
    if (categoryData.isGroup) {
      (categoryData.subcategoryNames || []).forEach(subName => {
        const subData = libraryData.categories[subName];
        if (!subData || !subData.books) return;
        subData.books.forEach(book => {
          searchIndex.push({ type: 'book', categoryName: subName, title: book.title, description: book.description, note: book.note || '', book });
          if (book.chapters) {
            book.chapters.forEach(chapter => {
              searchIndex.push({ type: 'chapter', categoryName: subName, bookTitle: book.title, title: chapter.title, page: chapter.page, url: chapter.url, book, chapter });
            });
          }
        });
      });
      return;
    }
    if (!categoryData.books) return;
    categoryData.books.forEach(book => {
      // Add book to search index
      searchIndex.push({
        type: 'book',
        categoryName: categoryName,
        title: book.title,
        description: book.description,
        note: book.note || '',
        book: book
      });
      
      // Add chapters to search index if they exist
      if (book.chapters) {
        book.chapters.forEach(chapter => {
          searchIndex.push({
            type: 'chapter',
            categoryName: categoryName,
            bookTitle: book.title,
            title: chapter.title,
            page: chapter.page,
            url: chapter.url,
            book: book,
            chapter: chapter
          });
        });
      }
    });
  });
}

// Render the library categories and books
function renderLibrary() {
  const categoriesGrid = document.getElementById('categories-grid');
  if (!categoriesGrid) return;
  
  categoriesGrid.innerHTML = '';
  
  Object.entries(libraryData.categories).forEach(([categoryName, categoryData]) => {
    // Skip individually hidden categories (they appear inside the group)
    if (categoryData.hidden) return;
    const categoryElement = categoryData.isGroup
      ? createGroupCategoryElement(categoryName, categoryData)
      : createCategoryElement(categoryName, categoryData);
    categoriesGrid.appendChild(categoryElement);
  });
}

// Create a group category element (e.g. "Translated Editions") with nested sub-accordions
function createGroupCategoryElement(groupName, groupData) {
  const subNames = groupData.subcategoryNames || [];
  const totalBooks = subNames.reduce((sum, n) => {
    const sub = libraryData.categories[n];
    return sum + (sub && sub.books ? sub.books.length : 0);
  }, 0);

  const groupDiv = document.createElement('div');
  groupDiv.className = 'category collapsed';
  groupDiv.setAttribute('data-category', groupName);

  // Build horizontal language header buttons
  const langHeadersHTML = subNames.map((name, i) => {
    const label = name.replace(/^-\s*/, '').replace(/\s+Translations$/i, '');
    const bookCount = (libraryData.categories[name]?.books?.length) || 0;
    const bookCountText = bookCount === 1 ? '1 book' : `${bookCount} books`;
    return `
      <button class="lang-header-btn" data-lang-index="${i}" aria-expanded="false">
        <span class="lang-header-toggle">+</span>
        <span class="lang-header-label">${label}</span>
        <span class="lang-header-count">${bookCountText}</span>
      </button>`;
  }).join('');

  groupDiv.innerHTML = `
    <div class="category-header" data-category="${groupName}">
      <button class="expand-toggle" aria-label="Expand section" data-category="${groupName}"></button>
      <div class="category-header-content">
        <h2 class="category-title">${groupName}</h2>
        <div class="category-function">${groupData.function}</div>
        <div class="category-approach">${groupData.approach}</div>
      </div>
      <div class="category-summary">
        <span class="book-count">${subNames.length} languages · ${totalBooks} books</span>
      </div>
    </div>
    <div class="category-content">
      <div class="lang-headers-row">${langHeadersHTML}</div>
      <div class="lang-content-pane" hidden></div>
    </div>
  `;

  // Pre-build panels keyed by index
  const panels = subNames.map((subName) => {
    const subData = libraryData.categories[subName];
    const pane = document.createElement('div');
    pane.className = 'books-grid';
    pane.innerHTML = subData?.books ? subData.books.map(book => createBookCardHTML(book)).join('') : '';
    return pane;
  });

  const contentPane = groupDiv.querySelector('.lang-content-pane');
  let activeIndex = -1;

  groupDiv.querySelector('.lang-headers-row').addEventListener('click', e => {
    const btn = e.target.closest('.lang-header-btn');
    if (!btn) return;
    const idx = parseInt(btn.dataset.langIndex, 10);

    // Toggle: clicking the open one closes it
    if (idx === activeIndex) {
      btn.setAttribute('aria-expanded', 'false');
      btn.querySelector('.lang-header-toggle').textContent = '+';
      btn.classList.remove('lang-header-btn--active');
      contentPane.hidden = true;
      contentPane.innerHTML = '';
      activeIndex = -1;
      return;
    }

    // Switch to new language
    groupDiv.querySelectorAll('.lang-header-btn').forEach(b => {
      b.setAttribute('aria-expanded', 'false');
      b.querySelector('.lang-header-toggle').textContent = '+';
      b.classList.remove('lang-header-btn--active');
    });

    btn.setAttribute('aria-expanded', 'true');
    btn.querySelector('.lang-header-toggle').textContent = '−';
    btn.classList.add('lang-header-btn--active');

    contentPane.hidden = false;
    contentPane.innerHTML = '';
    contentPane.appendChild(panels[idx]);
    activeIndex = idx;
  });

  return groupDiv;
}

// Create category element with expand/collapse functionality
// isNested = true when rendered inside a group
function createCategoryElement(categoryName, categoryData, isNested = false) {
  const categoryDiv = document.createElement('div');
  categoryDiv.className = `category collapsed${isNested ? ' category--nested' : ''}`;
  categoryDiv.setAttribute('data-category', categoryName);
  
  const bookCount = categoryData.books ? categoryData.books.length : 0;
  const bookCountText = bookCount === 1 ? '1 book' : `${bookCount} books`;
  
  categoryDiv.innerHTML = `
    <div class="category-header" data-category="${categoryName}">
      <button class="expand-toggle" aria-label="Expand section" data-category="${categoryName}"></button>
      <div class="category-header-content">
        <h2 class="category-title">${categoryName}</h2>
        ${categoryData.function ? `<div class="category-function">${categoryData.function}</div>` : ''}
        ${categoryData.approach ? `<div class="category-approach">${categoryData.approach}</div>` : ''}
      </div>
      <div class="category-summary">
        <span class="book-count">${bookCountText}</span>
      </div>
    </div>
    <div class="category-content">
      <div class="books-grid">
        ${categoryData.books ? categoryData.books.map(book => createBookCardHTML(book)).join('') : ''}
      </div>
    </div>
  `;
  
  return categoryDiv;
}

// Create book card HTML
function createBookCardHTML(book) {
  const hasNote = book.note && book.note.length > 0;

  // Get book slug for thumbnail lookup
  const slug = getBookSlug(book);
  const thumbnailPath = slug ? `images/thumbnails/${slug}.png` : '';

  // Check for an alternate Farsi cover in images/thumbnails/alt-farsi/
  const altFilename = slug ? FARSI_ALT_THUMBNAILS[slug] : null;
  const altThumbnailPath = altFilename
    ? `images/thumbnails/alt-farsi/${altFilename}`
    : '';

  const thumbHTML = thumbnailPath ? `
    <div class="book-thumbnail${altThumbnailPath ? ' has-alt-thumbnail' : ''}"
         data-thumb-default="${thumbnailPath}"
         ${altThumbnailPath
           ? `data-thumb-alt="${altThumbnailPath}" data-thumb-state="default"`
           : ''}>
      <img src="${thumbnailPath}"
           alt="${book.title}"
           onerror="this.parentElement.style.display='none';">
      ${altThumbnailPath
        ? `<div class="thumb-alt-badge" title="Click thumbnail to see alternative cover">⟳</div>`
        : ''}
    </div>
  ` : '';

  return `
    <div class="book-card" data-book-title="${book.title}" data-book-slug="${slug || ''}">
      ${thumbHTML}
      <h3 class="book-title">${book.title}</h3>
      <p class="book-description">${book.description}</p>
      ${hasNote ? `<div class="book-note">${book.note}</div>` : ''}
      <div class="book-actions">
        <button class="btn btn--primary btn--sm quick-read-btn" data-pdf-url="${book.pdf_url}">
          <span class="external-icon">📖</span>Quick Read
        </button>
        <button class="btn btn--outline btn--sm view-details-btn">
          <span class="external-icon">📋</span>View Details
        </button>
      </div>
    </div>
  `;
}

// Toggle category expansion
function toggleCategory(categoryName) {
  const categoryElement = document.querySelector(`[data-category="${categoryName}"].category`);
  if (!categoryElement) return;
  
  const isCollapsed = categoryElement.classList.contains('collapsed');
  
  if (isCollapsed) {
    categoryElement.classList.remove('collapsed');
    categoryElement.classList.add('expanded');
  } else {
    categoryElement.classList.remove('expanded');
    categoryElement.classList.add('collapsed');
  }
}

// Setup event listeners
function setupEventListeners() {
  const searchInput = document.getElementById('search-input');
  const searchClear = document.getElementById('search-clear');
  const searchBtn = document.getElementById('search-btn');


    // Search functionality - BUTTON TRIGGERED ONLY (not on real-time input)
    if (searchBtn) {
      searchBtn.addEventListener('click', handleSearch);
    }

    // Allow Enter key to trigger search from input field
    if (searchInput) {
      searchInput.addEventListener('keydown', function(e) {
        if (e.key === 'Enter') {
          e.preventDefault();
          handleSearch();
        }
        if (e.key === 'Escape') {
          clearSearch();
        }
      });

      searchInput.addEventListener('focus', function() {
        console.log('Search input focused');
      });
    }

  
  if (searchClear) {
    searchClear.addEventListener('click', function(e) {
      e.preventDefault();
      clearSearch();
    });
  }
  
  // Event delegation for click events - but avoid interfering with input
  document.body.addEventListener('click', function(e) {
    // Skip if clicking on search input or its container
    if (e.target.closest('.search-container')) {
      return;
    }
    
    // Handle expand/collapse toggle buttons
    if (e.target.classList.contains('expand-toggle')) {
      e.preventDefault();
      e.stopPropagation();
      
      const categoryName = e.target.getAttribute('data-category');
      if (categoryName) {
        toggleCategory(categoryName);
      }
      return;
    }
    
    // Handle category header clicks (but not the toggle button)
    if (e.target.closest('.category-header') && !e.target.classList.contains('expand-toggle')) {
      e.preventDefault();
      const header = e.target.closest('.category-header');
      const categoryName = header.getAttribute('data-category');
      if (categoryName) {
        toggleCategory(categoryName);
      }
      return;
    }
    
    // Handle quick read buttons
     if (e.target.closest('.quick-read-btn')) {
      e.preventDefault();
      e.stopPropagation();
      const button = e.target.closest('.quick-read-btn');
      const pdfUrl = button.getAttribute('data-pdf-url');
      if (pdfUrl) {
        // Use the enhanced PDF opening function
        openPDFWithFix(pdfUrl);
      }
      return;
    }
    
    // Handle view details buttons
    if (e.target.closest('.view-details-btn')) {
      e.preventDefault();
      e.stopPropagation();
      const bookCard = e.target.closest('.book-card');
      if (bookCard) {
        const slug = bookCard.getAttribute('data-book-slug');
        const book = findBookBySlug(slug) || findBookByTitle(bookCard.getAttribute('data-book-title'));
        if (book) {
          openBookModal(book);
        }
      }
      return;
    }
    
    // Handle alt-thumbnail cycling (Farsi books with two covers)
    if (e.target.closest('.has-alt-thumbnail')) {
      e.preventDefault();
      e.stopPropagation();
      const thumbDiv = e.target.closest('.has-alt-thumbnail');
      const img = thumbDiv.querySelector('img');
      const state = thumbDiv.getAttribute('data-thumb-state');
      if (state === 'default') {
        img.src = thumbDiv.getAttribute('data-thumb-alt');
        thumbDiv.setAttribute('data-thumb-state', 'alt');
        thumbDiv.classList.add('showing-alt');
      } else {
        img.src = thumbDiv.getAttribute('data-thumb-default');
        thumbDiv.setAttribute('data-thumb-state', 'default');
        thumbDiv.classList.remove('showing-alt');
      }
      return;
    }

    // Handle book card clicks (but not on actions)
    if (e.target.closest('.book-card') && !e.target.closest('.book-actions')) {
      e.preventDefault();
      const bookCard = e.target.closest('.book-card');
      const slug = bookCard.getAttribute('data-book-slug');
      const book = findBookBySlug(slug) || findBookByTitle(bookCard.getAttribute('data-book-title'));
      if (book) {
        openBookModal(book);
      }
      return;
    }
    
    // Handle search result clicks
    if (e.target.closest('.result-item')) {
      e.preventDefault();
      const resultItem = e.target.closest('.result-item');
      const resultType = resultItem.getAttribute('data-result-type');
      
      if (resultType === 'chapter') {
        const chapterUrl = resultItem.getAttribute('data-chapter-url');
        if (chapterUrl) {
          window.open(chapterUrl, '_blank', 'noopener,noreferrer');
        }
      } else {
        const slug = resultItem.getAttribute('data-book-slug');
        const book = findBookBySlug(slug) || findBookByTitle(resultItem.getAttribute('data-book-title'));
        if (book) {
          openBookModal(book);
        }
      }
      return;
    }
    
    // Modal close functionality
    if (e.target.id === 'modal-close' || e.target.id === 'modal-backdrop') {
      e.preventDefault();
      closeBookModal();
      return;
    }
  });
  
  // Keyboard navigation
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape' && currentModal) {
      closeBookModal();
    }
  });

  // NEW: Close button for search results
  const searchResultsClose = document.getElementById('search-results-close');
  if (searchResultsClose) {
    searchResultsClose.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();
      clearSearch();
    });
  }

  // NEW: Click overlay background to close
  const searchOverlay = document.getElementById('search-overlay');
  if (searchOverlay) {
    searchOverlay.addEventListener('click', (e) => {
      // Only close if clicking the overlay itself, not the results
      if (e.target === searchOverlay) {
        clearSearch();
      }
    });
  }

  // NEW: Escape key to close search results
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      const searchOverlay = document.getElementById('search-overlay');
      if (searchOverlay && searchOverlay.classList.contains('active')) {
        clearSearch();
      }
    }
  });
}


// Handle search input
function handleSearch(e) {
  // Don't require event target anymore
  const searchInput = document.getElementById('search-input');
  const searchClear = document.getElementById('search-clear');

  if (!searchInput) return;

  const query = searchInput.value.trim().toLowerCase();

  console.log('Search query:', query); // Debug log

  if (query.length === 0) {
    clearSearch();
    return;
  }

  if (searchClear) {
    searchClear.classList.add('visible');
  }

  const results = searchIndex.filter(item => {
    const titleMatch = item.title.toLowerCase().includes(query);
    const descMatch = item.description && item.description.toLowerCase().includes(query);
    const noteMatch = item.note && item.note.toLowerCase().includes(query);
    const bookTitleMatch = item.bookTitle && item.bookTitle.toLowerCase().includes(query);

    return titleMatch || descMatch || noteMatch || bookTitleMatch;
  });

  console.log('Search results:', results.length); // Debug log
  displaySearchResults(results, query);
}


// Display search results
function displaySearchResults(results, query) {
  const searchResults = document.getElementById('search-results');
  const resultsContainer = document.getElementById('results-container');
  const libraryContent = document.getElementById('library-content');
  const searchOverlay = document.getElementById('search-overlay');

  if (!searchResults || !resultsContainer || !libraryContent) return;

  // Activate overlay - fade everything to black except results
  if (searchOverlay) {
    searchOverlay.classList.add('active');
  }

  if (results.length === 0) {
    resultsContainer.innerHTML = `<p>No results found for "${query}"</p>`;
  } else {
    resultsContainer.innerHTML = results.map(result => {
      if (result.type === 'book') {
        const slug = getBookSlug(result.book) || '';
        return `
          <div class="result-item" data-result-type="book" data-book-title="${result.title}" data-book-slug="${slug}">
            <div class="result-type">Book</div>
            <div class="result-title">${highlightQuery(result.title, query)}</div>
            <div class="result-description">${highlightQuery(result.description, query)}</div>
          </div>
        `;
      } else {
        const slug = getBookSlug(result.book) || '';
        return `
          <div class="result-item" data-result-type="chapter" data-book-title="${result.bookTitle}" data-book-slug="${slug}" data-chapter-url="${result.url}">
            <div class="result-type">Chapter • ${result.bookTitle}</div>
            <div class="result-title">${highlightQuery(result.title, query)} <span style="color: var(--color-text-secondary);">(Page ${result.page})</span></div>
            <div class="result-description">Click to jump directly to this chapter</div>
          </div>
        `;
      }
    }).join('');
  }

    // Hide body scrollbar
  document.body.classList.add('search-overlay-active');

  searchResults.style.display = 'block';
  libraryContent.style.display = 'none';
}

// Highlight search query in text
function highlightQuery(text, query) {
  if (!query || !text) return text;
  
  const regex = new RegExp(`(${escapeRegex(query)})`, 'gi');
  return text.replace(regex, '<mark style="background: var(--color-bg-2); color: var(--color-text);">$1</mark>');
}

// Escape special regex characters
function escapeRegex(string) {
  return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// Clear search
function clearSearch() {
  const searchInput = document.getElementById('search-input');
  const searchClear = document.getElementById('search-clear');
  const searchResults = document.getElementById('search-results');
  const libraryContent = document.getElementById('library-content');
  const searchOverlay = document.getElementById('search-overlay');

  if (searchInput) searchInput.value = '';
  if (searchClear) searchClear.classList.remove('visible');
  if (searchResults) searchResults.style.display = 'none';
  if (libraryContent) libraryContent.style.display = 'block';

  // Remove overlay - restore normal page view
  if (searchOverlay) {
    searchOverlay.classList.remove('active');
  }
}

// Find book by its URL slug (unique — no two books share a slug)
function findBookBySlug(slug) {
  if (!slug) return null;
  for (const categoryData of Object.values(libraryData.categories)) {
    if (!categoryData.books) continue;
    for (const b of categoryData.books) {
      if (getBookSlug(b) === slug) return b;
    }
  }
  return null;
}

// Find book by title — falls back gracefully when slug lookup isn't available.
// Accepts an optional hintUrl to disambiguate editions that share a display
// title (e.g. Dari vs Farsi editions of the same book).
function findBookByTitle(title, hintUrl) {
  const matches = [];
  for (const categoryData of Object.values(libraryData.categories)) {
    if (!categoryData.books) continue;
    for (const b of categoryData.books) {
      if (b.title === title) matches.push(b);
    }
  }
  if (matches.length === 0) return null;
  if (matches.length === 1 || !hintUrl) return matches[0];
  const preferred = matches.find(
    b => (b.main_url && b.main_url.includes(hintUrl)) ||
         (b.pdf_url  && b.pdf_url.includes(hintUrl))
  );
  return preferred || matches[0];
}

